function parseRoute(hash: string): Route { const value = hash.replace(/^#/, '') || '/'; if (value === '/' || value === '') return { page: 'overview' }; if (value === '/quick-setup') return { page: 'quick-setup' }; if (value === '/features' || value === '/config') return { page: 'features' }; if (value === '/activity') return { page: 'activity' }; if (value === '/rank-card') return { page: 'rank-card' }; if (value.startsWith('/config/')) return { page: 'detail', key: decodeURIComponent(value.slice('/config/'.length)) }; return { page: 'overview' }; }

const quickSetupSteps: Array<{ key: QuickSetupStepKey; label: string; description: string }> = [
  { key: 'welcome', label: 'Receber quem chega', description: 'Mensagem, canal e cargo inicial.' },
  { key: 'roles', label: 'Dar escolhas aos membros', description: 'Painel de cargos com botões.' },
  { key: 'moderation', label: 'Moderação base', description: 'Registos e ações consistentes.' },
  { key: 'protection', label: 'Proteção automática', description: 'Perfis anti-spam e anti-raid.' },
];

function defaultQuickSetupState(guildId: string): QuickSetupState {
  return { guildId, status: 'not_started', currentStep: 'welcome', revision: 0, steps: quickSetupSteps.map(({ key }) => ({ key, status: 'pending' })), createdResources: [] };
}

function App() {
  const [youtubeSubscriptions, setYoutubeSubscriptions] = useState<YouTubeSubscription[]>([]);
  const [rssSubscriptions, setRssSubscriptions] = useState<RssSubscription[]>([]);
  const [twitchSubscriptions, setTwitchSubscriptions] = useState<TwitchSubscription[]>([]);
  const [route, setRoute] = useState<Route>(() => parseRoute(window.location.hash));
  const [me, setMe] = useState<Me | null>(null); const [guilds, setGuilds] = useState<Guild[]>(demoGuilds); const [guildContext, setGuildContext] = useState<GuildContext | null>(null); const [quickSetup, setQuickSetup] = useState<QuickSetupState | null>(null); const [features, setFeatures] = useState<Feature[]>(() => demoFeatures.concat(additionalFeatures).map(presentFeature)); const [cases, setCases] = useState<CaseRecord[]>([]); const [audit, setAudit] = useState<AuditRecord[]>([]); const [stats, setStats] = useState({ totalCases: 0 }); const [quota, setQuota] = useState({ plan: 'Free', limits: {} as Record<string, number>, usage: {} as Record<string, number> });
  const [rankConfig, setRankConfig] = useState(defaultRankCard); const [savedRankConfig, setSavedRankConfig] = useState(defaultRankCard); const [detailConfig, setDetailConfig] = useState<FeatureConfig>({}); const [savedDetailConfig, setSavedDetailConfig] = useState<FeatureConfig>({}); const [detailEnabled, setDetailEnabled] = useState(false); const [detailRevision, setDetailRevision] = useState(0); const [status, setStatus] = useState<'loading' | 'ready' | 'error' | 'auth' | 'saving'>('loading'); const [message, setMessage] = useState(''); const [authError, setAuthError] = useState(''); const [authLoading, setAuthLoading] = useState(false); const [search, setSearch] = useState(''); const [filter, setFilter] = useState<Category>('all'); const [detailLoading, setDetailLoading] = useState(false);

  const navigate = (path: string) => { const next = parseRoute(path); if (window.location.hash === path) setRoute(next); else window.location.hash = path; };
  useEffect(() => { const onHash = () => setRoute(parseRoute(window.location.hash)); window.addEventListener('hashchange', onHash); if (!window.location.hash) window.location.hash = '#/'; return () => window.removeEventListener('hashchange', onHash); }, []);
  useEffect(() => {
    if (localPreviewMode) { setMe({ id: 'demo', guildId: 'demo', expiresAt: new Date(Date.now() + 86_400_000).toISOString(), dbOk: true }); setStatus('ready'); return; }
    void Promise.all([api.me(), api.guilds().catch(() => ({ guilds: demoGuilds })), api.features().catch(() => ({ guildId: '', features: demoFeatures.concat(additionalFeatures) })), api.stats().catch(() => ({ totalCases: 0, guildId: '' })), api.cases().catch(() => ({ cases: [] })), api.audit().catch(() => ({ events: [] })), api.quotas().catch(() => ({ plan: 'Free', limits: {}, usage: {} })), api.rankCard().catch(() => ({ guildId: '', config: defaultRankCard }))]).then(([nextMe, nextGuilds, nextFeatures, nextStats, nextCases, nextAudit, nextQuota, nextRank]) => { setMe(nextMe); setGuilds(nextGuilds.guilds); setFeatures(nextFeatures.features.map(presentFeature)); setStats(nextStats); setCases(nextCases.cases); setAudit(nextAudit.events); setQuota(nextQuota); setRankConfig(nextRank.config); setSavedRankConfig(nextRank.config); setStatus('ready'); }).catch((cause: unknown) => { setMessage(cause instanceof Error ? cause.message : 'Não foi possível carregar o painel.'); setStatus('error'); });
   }, []);
  useEffect(() => {
    const guildId = me?.guildId ?? 'demo';
    if (localPreviewMode) {
      try { const stored = localStorage.getItem(`vh_quick_setup_${guildId}`); setQuickSetup(stored ? JSON.parse(stored) as QuickSetupState : defaultQuickSetupState(guildId)); } catch { setQuickSetup(defaultQuickSetupState(guildId)); }
      setGuildContext({ guildId, name: guilds[0]?.name ?? 'Servidor de demonstração', permissions: 'demo', channels: [{ id: 'demo-general', name: 'geral', type: 'text' }, { id: 'demo-rules', name: 'regras', type: 'text' }], roles: [{ id: 'demo-member', name: 'Membro', position: 1 }], hierarchy: { known: true }, capabilities: { channelSelectors: true, roleSelectors: true, permissionPreflight: true }, stale: false });
      return;
    }
    void api.quickSetup().then(setQuickSetup).catch(() => setQuickSetup(defaultQuickSetupState(guildId)));
    void api.guildContext().then(setGuildContext).catch(() => undefined);
  }, [me?.guildId, guilds]);
  useEffect(() => {
    if (route.page !== 'overview' || !quickSetup || quickSetup.status !== 'not_started') return;
    const key = `vh_quick_setup_intro_${quickSetup.guildId}`;
    try { if (sessionStorage.getItem(key)) return; sessionStorage.setItem(key, '1'); } catch { /* storage opcional */ }
    window.location.hash = '#/quick-setup';
  }, [route.page, quickSetup]);
   async function startLogin() { setAuthLoading(true); setAuthError(''); try { await api.startOAuth(); } catch (cause) { setAuthError(cause instanceof Error ? cause.message : 'Não foi possível iniciar o acesso com Discord.'); setAuthLoading(false); } }
  useEffect(() => {
    if (!localPreviewMode) {
      void api.youtubeSubscriptions().then((result) => setYoutubeSubscriptions(result.subscriptions)).catch(() => undefined);
      void api.rssSubscriptions().then((result) => setRssSubscriptions(result.subscriptions)).catch(() => undefined);
      void api.twitchSubscriptions().then((result) => setTwitchSubscriptions(result.subscriptions)).catch(() => undefined);
    }
  }, []);
  useEffect(() => {
    if (route.page !== 'detail' || !route.key) return;
    setDetailLoading(true); const fallback = defaults[route.key] ?? {};
    if (localPreviewMode) { setDetailConfig({ ...fallback }); setSavedDetailConfig({ ...fallback }); setDetailEnabled(features.find((item) => item.key === route.key)?.enabled ?? false); setDetailLoading(false); return; }
    void api.feature(route.key).then((result) => { setDetailConfig({ ...fallback, ...result.config }); setSavedDetailConfig({ ...fallback, ...result.config }); setDetailEnabled(result.enabled); setDetailRevision(result.revision ?? 0); }).catch(() => { setDetailConfig({ ...fallback }); setSavedDetailConfig({ ...fallback }); setDetailEnabled(features.find((item) => item.key === route.key)?.enabled ?? false); setDetailRevision(0); }).finally(() => setDetailLoading(false));
  }, [route.page, route.key, features]);
  useEffect(() => {
    const subscription = route.key === 'social.youtube' ? youtubeSubscriptions[0] : undefined;
    if (route.page === 'detail' && route.key === 'social.youtube' && subscription) {
      setDetailConfig((current) => ({ ...current, sourceChannelId: subscription.sourceChannelId, targetChannelId: subscription.targetChannelId, messageTemplate: subscription.messageTemplate, mention: subscription.mention, intervalSeconds: subscription.intervalSeconds }));
      setSavedDetailConfig((current) => ({ ...current, sourceChannelId: subscription.sourceChannelId, targetChannelId: subscription.targetChannelId, messageTemplate: subscription.messageTemplate, mention: subscription.mention, intervalSeconds: subscription.intervalSeconds }));
      setDetailEnabled(subscription.enabled);
    }
  }, [route.page, route.key, youtubeSubscriptions]);
  useEffect(() => {
    const subscription = route.key === 'social.rss' ? rssSubscriptions[0] : undefined;
    if (route.page === 'detail' && route.key === 'social.rss' && subscription) {
      setDetailConfig((current) => ({ ...current, feedUrl: subscription.feedUrl, targetChannelId: subscription.targetChannelId, messageTemplate: subscription.messageTemplate, mention: subscription.mention, intervalSeconds: subscription.intervalSeconds }));
      setSavedDetailConfig((current) => ({ ...current, feedUrl: subscription.feedUrl, targetChannelId: subscription.targetChannelId, messageTemplate: subscription.messageTemplate, mention: subscription.mention, intervalSeconds: subscription.intervalSeconds }));
      setDetailEnabled(subscription.enabled);
    }
  }, [route.page, route.key, rssSubscriptions]);
  useEffect(() => {
    const subscription = route.key === 'social.twitch' ? twitchSubscriptions[0] : undefined;
    if (route.page === 'detail' && route.key === 'social.twitch' && subscription) {
      setDetailConfig((current) => ({ ...current, sourceLogin: subscription.sourceLogin, targetChannelId: subscription.targetChannelId, messageTemplate: subscription.messageTemplate, mention: subscription.mention }));
      setSavedDetailConfig((current) => ({ ...current, sourceLogin: subscription.sourceLogin, targetChannelId: subscription.targetChannelId, messageTemplate: subscription.messageTemplate, mention: subscription.mention }));
      setDetailEnabled(subscription.enabled);
    }
  }, [route.page, route.key, twitchSubscriptions]);

  const currentGuild = guilds.find((guild) => guild.id === me?.guildId) ?? guilds[0]; const currentFeature = features.find((item) => item.key === route.key); const detailDirty = JSON.stringify(detailConfig) !== JSON.stringify(savedDetailConfig); const rankDirty = JSON.stringify(rankConfig) !== JSON.stringify(savedRankConfig); const dirty = route.page === 'detail' ? detailDirty : route.page === 'rank-card' ? rankDirty : false;
  const filteredFeatures = useMemo(() => { const unique = Array.from(new Map(features.map((item) => [item.key, item])).values()); return unique.filter((item) => (filter === 'all' || item.category === filter) && item.label.toLocaleLowerCase().includes(search.toLocaleLowerCase())); }, [features, filter, search]);
  async function switchGuild(guildId: string) { if (localPreviewMode) { setMe((current) => current ? { ...current, guildId } : current); return; } try { await api.switchGuild(guildId); window.location.reload(); } catch (cause) { setMessage(cause instanceof Error ? cause.message : 'Não foi possível trocar de servidor.'); } }
  async function saveDetail() { if (!route.key) return; setStatus('saving'); try { const result = localPreviewMode ? { enabled: detailEnabled, config: detailConfig, revision: detailRevision } : await api.saveFeature(route.key, detailEnabled, detailConfig, detailRevision); setFeatures((items) => items.map((item) => item.key === route.key ? { ...item, enabled: result.enabled } : item)); setDetailConfig(result.config); setSavedDetailConfig(result.config); setDetailRevision(result.revision ?? detailRevision); setStatus('ready'); setMessage(localPreviewMode ? 'Pré-visualização guardada neste navegador.' : 'Configuração publicada no servidor.'); } catch (cause) { setStatus('error'); setMessage(cause instanceof Error ? cause.message : 'Não foi possível guardar.'); } }
  async function testDetail() { if (!route.key) return; try { if (route.key === 'social.rss') { const feedUrl = String(detailConfig.feedUrl ?? '').trim(); if (!feedUrl) { setMessage('Indica primeiro o URL do feed RSS/Atom.'); return; } if (localPreviewMode) { setMessage('A confirmação do feed aparece quando o painel estiver ligado à API.'); return; } const result = await api.rssPreview(feedUrl); const latest = result.feed.latest; setMessage(latest ? `Feed confirmado: ${result.feed.title || 'sem título'} · Última publicação: ${latest.title || 'sem título'}.` : `Feed confirmado: ${result.feed.title || 'sem título'}.`); return; } if (route.key === 'social.twitch') { const login = String(detailConfig.sourceLogin ?? '').trim(); if (!login) { setMessage('Indica primeiro o nome do canal Twitch.'); return; } if (localPreviewMode) { setMessage('A validação do canal Twitch aparece quando o painel estiver ligado à API.'); return; } const result = await api.twitchChannel(login); setMessage(`Canal confirmado: ${result.channel.display_name} (@${result.channel.login}).`); return; } const result = await api.testFeature(route.key, detailConfig); const errors = result.issues.filter((issue) => issue.severity === 'error'); setMessage(errors.length ? errors.map((issue) => issue.message).join(' ') : result.effects.length ? `Simulação: ${result.effects.join(' · ')}` : 'Simulação concluída — nenhuma ação real foi aplicada.'); } catch { setMessage(route.key === 'social.rss' ? 'Não foi possível ler este feed. Confirma o URL e tenta novamente.' : route.key === 'social.twitch' ? 'Não foi possível validar o canal Twitch. Confirma o nome e as credenciais do servidor.' : 'A simulação está disponível quando a API estiver ligada.'); } }
  async function saveRankCard() { setStatus('saving'); try { const result = localPreviewMode ? { config: rankConfig } : await api.saveRankCard(rankConfig); setRankConfig(result.config); setSavedRankConfig(result.config); setStatus('ready'); setMessage(localPreviewMode ? 'Pré-visualização guardada neste navegador.' : 'XP card publicado no servidor.'); } catch (cause) { setStatus('error'); setMessage(cause instanceof Error ? cause.message : 'Não foi possível publicar.'); } }
  async function applyQuickSetupStep(step: QuickSetupStepKey, config: FeatureConfig, enabled = true): Promise<boolean> {
    setStatus('saving');
    try {
      const writes: Array<{ key: string; config: FeatureConfig; enabled: boolean }> = [];
      if (step === 'welcome') writes.push({ key: 'support.welcome', config, enabled });
      if (step === 'roles') writes.push({ key: 'community.role_panels', config, enabled });
      if (step === 'moderation') writes.push({ key: 'management.moderation', config, enabled });
      if (step === 'protection') {
        const profile = String(config.profile ?? 'balanced');
        const profiles: Record<string, { antispam: FeatureConfig; antiRaid: FeatureConfig }> = {
          monitor: { antispam: { ...defaults['protection.antispam'], sensitivity: 'gentle', floodCount: 8, duplicateLimit: 4, timeoutSeconds: 0, mentionLimit: 8, alertOnly: true, logChannel: config.logChannel ?? '' }, antiRaid: { ...defaults['protection.anti_raid'], joinThreshold: 12, alertOnly: true, alertChannel: config.logChannel ?? '' } },
          balanced: { antispam: { ...defaults['protection.antispam'], sensitivity: 'balanced', floodCount: 6, duplicateLimit: 3, timeoutSeconds: 60, mentionLimit: 5, alertOnly: false, logChannel: config.logChannel ?? '' }, antiRaid: { ...defaults['protection.anti_raid'], joinThreshold: 10, alertOnly: true, alertChannel: config.logChannel ?? '' } },
          strict: { antispam: { ...defaults['protection.antispam'], sensitivity: 'strict', floodCount: 5, duplicateLimit: 2, timeoutSeconds: 300, mentionLimit: 4, alertOnly: false, logChannel: config.logChannel ?? '' }, antiRaid: { ...defaults['protection.anti_raid'], joinThreshold: 8, alertOnly: false, alertChannel: config.logChannel ?? '' } },
        };
        const selected = profiles[profile] ?? profiles.balanced;
        writes.push({ key: 'protection.antispam', config: selected.antispam, enabled });
        writes.push({ key: 'protection.anti_raid', config: selected.antiRaid, enabled });
      }
      if (!localPreviewMode) for (const write of writes) await api.saveFeature(write.key, write.enabled, write.config);
      const previous = quickSetup ?? defaultQuickSetupState(me?.guildId ?? 'demo');
      const next = localPreviewMode ? { ...previous, revision: previous.revision + 1, status: 'in_progress' as const, steps: previous.steps.map((item) => item.key === step ? { ...item, status: 'applied' as const } : item) } : await api.saveQuickSetupStep(step, { status: 'applied', config, enabled, expectedRevision: previous.revision });
      if (!localPreviewMode && next.draft && (step === 'welcome' || step === 'roles')) {
        const normalizedConfig = next.draft as FeatureConfig;
        const normalizedKey = step === 'welcome' ? 'support.welcome' : 'community.role_panels';
        await api.saveFeature(normalizedKey, enabled, { ...config, ...normalizedConfig });
      }
      if (!localPreviewMode && next.draft && step === 'protection') {
        const normalizedConfig = next.draft as FeatureConfig;
        const channelId = String(normalizedConfig.logChannel ?? '').trim();
        if (channelId) {
          const antispam = writes.find((write) => write.key === 'protection.antispam');
          const antiRaid = writes.find((write) => write.key === 'protection.anti_raid');
          if (antispam) await api.saveFeature(antispam.key, antispam.enabled, { ...antispam.config, logChannel: channelId });
          if (antiRaid) await api.saveFeature(antiRaid.key, antiRaid.enabled, { ...antiRaid.config, alertChannel: channelId });
        }
      }
      const normalized = next.steps.every((item) => item.status !== 'pending') ? { ...next, status: 'completed' as const, currentStep: null } : next;
      setQuickSetup(normalized); if (localPreviewMode) localStorage.setItem(`vh_quick_setup_${me?.guildId ?? 'demo'}`, JSON.stringify(normalized));
      setFeatures((items) => items.map((item) => writes.some((write) => write.key === item.key) ? { ...item, enabled } : item));
      setStatus('ready'); setMessage(`${quickSetupSteps.find((item) => item.key === step)?.label ?? 'Etapa'} aplicada.`); return true;
    } catch (cause) { setStatus('error'); setMessage(cause instanceof Error ? cause.message : 'Não foi possível aplicar esta etapa.'); return false; }
  }
  async function skipQuickSetupStep(step: QuickSetupStepKey): Promise<boolean> {
    try { const previous = quickSetup ?? defaultQuickSetupState(me?.guildId ?? 'demo'); const next = localPreviewMode ? { ...previous, revision: previous.revision + 1, status: 'in_progress' as const, steps: previous.steps.map((item) => item.key === step ? { ...item, status: 'skipped' as const } : item) } : await api.saveQuickSetupStep(step, { status: 'skipped', expectedRevision: previous.revision }); setQuickSetup(next); if (localPreviewMode) localStorage.setItem(`vh_quick_setup_${me?.guildId ?? 'demo'}`, JSON.stringify(next)); return true; } catch (cause) { setMessage(cause instanceof Error ? cause.message : 'Não foi possível saltar esta etapa.'); return false; }
  }
  async function dismissQuickSetup() { try { const next = localPreviewMode ? { ...(quickSetup ?? defaultQuickSetupState(me?.guildId ?? 'demo')), status: 'dismissed' as const } : await api.dismissQuickSetup(); setQuickSetup(next); if (localPreviewMode) localStorage.setItem(`vh_quick_setup_${me?.guildId ?? 'demo'}`, JSON.stringify(next)); } catch { setMessage('A configuração rápida continua disponível na barra lateral.'); } }
  if (status === 'loading') return <div className="center"><div className="loader" /><p>A preparar o teu espaço de trabalho…</p></div>;
  if ((status === 'auth' || status === 'error') && !me) return <AuthScreen error={status === 'auth' ? authError : message} loading={authLoading} onLogin={() => void startLogin()} />;
  const title = route.page === 'detail' ? currentFeature?.label ?? 'Configuração' : pages.find((item) => item.id === route.page)?.label ?? 'Painel';
  const subtitle = route.page === 'overview' ? 'O essencial para deixares o servidor pronto.' : route.page === 'quick-setup' ? 'Prepara o essencial por etapas curtas, com revisão antes de publicar.' : route.page === 'features' ? 'Escolhe um tópico para abrir a configuração completa.' : route.page === 'activity' ? 'Vê o que aconteceu e mantém o controlo.' : route.page === 'rank-card' ? 'Cria uma carta de nível com a identidade do teu servidor.' : 'Configuração por servidor, com opções simples e avançadas.';
  return <div className="shell"><aside className="sidebar"><div className="logo"><span>✦</span><div><strong>VOZEN</strong><small>HELPER PANEL</small></div></div><div className="workspace"><small>SERVIDOR ATUAL</small><select value={currentGuild?.id ?? ''} onChange={(event) => void switchGuild(event.target.value)}>{guilds.map((guild) => <option value={guild.id} key={guild.id}>{guild.name}</option>)}</select><p>As alterações ficam isoladas neste servidor.</p></div><nav aria-label="Navegação principal">{pages.map((item) => <button key={item.id} className={route.page === item.id || (item.id === 'features' && route.page === 'detail') ? 'nav active' : 'nav'} onClick={() => navigate(item.id === 'overview' ? '#/' : `#/${item.id}`)}><span>{item.icon}</span><div><b>{item.label}</b><small>{item.hint}</small></div></button>)}</nav><div className="runtime"><i /> {localPreviewMode ? 'Pré-visualização local' : 'Sincronizado com Rust'}</div></aside><main className="main"><header><div><small className="eyebrow">{currentGuild?.name ?? 'WORKSPACE'} · HELPER</small><h1>{title}</h1><p className="subtitle">{subtitle}</p></div><div className="header-state"><span className="status-dot" /> {dirty ? 'Rascunho por publicar' : localPreviewMode ? 'Modo de demonstração' : 'Tudo sincronizado'}</div></header>{message && <div className="toast" role="status">{message}<button aria-label="Fechar" onClick={() => setMessage('')}>×</button></div>}{route.page === 'overview' && <Overview features={features} stats={stats} quota={quota} cases={cases} onOpen={navigate} />}{route.page === 'quick-setup' && <QuickSetup state={quickSetup ?? defaultQuickSetupState(currentGuild?.id ?? 'demo')} context={guildContext} onApply={applyQuickSetupStep} onSkip={skipQuickSetupStep} onDismiss={() => void dismissQuickSetup()} onOpen={navigate} />}{route.page === 'features' && <FeatureCatalogue features={filteredFeatures} filter={filter} setFilter={setFilter} search={search} setSearch={setSearch} onOpen={(key) => navigate(key === 'studio.rank_card' ? '#/rank-card' : `#/config/${encodeURIComponent(key)}`)} />}{route.page === 'activity' && <Activity cases={cases} audit={audit} />}{route.page === 'rank-card' && <RankCardEditor config={rankConfig} patch={(next) => setRankConfig((current) => ({ ...current, ...next }))} onSave={() => void saveRankCard()} onReset={() => setRankConfig(defaultRankCard)} saving={status === 'saving'} />}{route.page === 'detail' && (detailLoading ? <div className="loading-card card"><div className="loader" /><span>A carregar configuração…</span></div> : <FeatureDetail feature={currentFeature} config={detailConfig} enabled={detailEnabled} onEnabled={setDetailEnabled} onChange={(key, value) => setDetailConfig((current) => ({ ...current, [key]: value }))} onSave={() => void saveDetail()} onDiscard={() => { setDetailConfig(savedDetailConfig); setDetailEnabled(features.find((item) => item.key === route.key)?.enabled ?? false); }} onTest={() => void testDetail()} saving={status === 'saving'} onBack={() => navigate('#/features')} />)}</main></div>;
}

function QuickSetup({ state, context, onApply, onSkip, onDismiss, onOpen }: { state: QuickSetupState; context: GuildContext | null; onApply: (step: QuickSetupStepKey, config: FeatureConfig, enabled?: boolean) => Promise<boolean>; onSkip: (step: QuickSetupStepKey) => Promise<boolean>; onDismiss: () => void; onOpen: (path: string) => void }) {
  const [started, setStarted] = useState(state.status === 'in_progress' || state.status === 'completed');
  const [index, setIndex] = useState(Math.max(0, quickSetupSteps.findIndex((item) => item.key === state.currentStep)));
  const [applying, setApplying] = useState(false);
  const [draft, setDraft] = useState<Record<QuickSetupStepKey, FeatureConfig>>({
    welcome: { ...defaults['support.welcome'], mode: 'recommended', createChannel: true },
    roles: { ...defaults['community.role_panels'], template: 'notifications', createChannel: true, roleNames: 'Anúncios, Eventos, Novidades' },
    moderation: { ...defaults['management.moderation'], createChannel: true },
    protection: { profile: 'balanced', logChannel: '', createChannel: true },
  });
  useEffect(() => { setStarted(state.status === 'in_progress' || state.status === 'completed'); const next = quickSetupSteps.findIndex((item) => item.key === state.currentStep); if (next >= 0) setIndex(next); }, [state.status, state.currentStep]);
  const current = quickSetupSteps[index] ?? quickSetupSteps[0];
  const completed = state.status === 'completed' || state.steps.every((item) => item.status !== 'pending');
  const patch = (key: string, value: unknown) => setDraft((currentDraft) => ({ ...currentDraft, [current.key]: { ...currentDraft[current.key], [key]: value } }));
  const apply = async () => { setApplying(true); const ok = await onApply(current.key, draft[current.key], current.key !== 'moderation' || draft[current.key].mode !== 'off'); setApplying(false); if (ok && index < quickSetupSteps.length - 1) setIndex((value) => value + 1); };
  const skip = async () => { setApplying(true); const ok = await onSkip(current.key); setApplying(false); if (ok && index < quickSetupSteps.length - 1) setIndex((value) => value + 1); };
  if (!started && !completed) return <section className="quick-setup-page"><div className="quick-setup-hero card"><div className="quick-setup-mark">✧</div><small className="eyebrow">CONFIGURAÇÃO GUIADA · 2–4 MIN</small><h2>Põe o essencial a funcionar.</h2><p>Escolhe as bases do teu servidor. O Vozen mostra cada alteração antes de a aplicar e guarda o progresso por servidor.</p><div className="quick-setup-meta"><span>Servidor: <b>{context?.name ?? state.guildId}</b></span><span>{context?.capabilities.permissionPreflight ? 'Permissões verificadas' : 'Verificação de permissões pendente'}</span></div><div className="actions"><button className="secondary" onClick={onDismiss}>Agora não</button><button className="primary" onClick={() => setStarted(true)}>Preparar servidor <span>→</span></button></div></div></section>;
  if (completed) return <section className="quick-setup-page"><div className="quick-setup-complete card"><span className="success-mark">✓</span><small className="eyebrow">SERVIDOR PREPARADO</small><h2>Está tudo pronto.</h2><p>As escolhas do Quick Setup foram guardadas. Podes voltar aqui sempre que quiseres rever o essencial.</p><div className="setup-summary">{state.steps.map((step) => <div key={step.key}><span className={step.status === 'applied' ? 'summary-icon done' : 'summary-icon'}>{step.status === 'applied' ? '✓' : '–'}</span><div><b>{quickSetupSteps.find((item) => item.key === step.key)?.label}</b><small>{step.status === 'applied' ? 'Aplicado no servidor' : 'Ignorado nesta sessão'}</small></div></div>)}</div><div className="premium-panel"><small className="eyebrow">QUANDO QUISERES IR MAIS LONGE</small><h3>Funcionalidades Premium para o próximo passo</h3><div className="premium-grid"><PremiumCard icon="↗" title="Níveis e XP" text="Recompensas, anúncios de nível e XP card." /><PremiumCard icon="□" title="Tickets avançados" text="Equipas, transcripts e SLA para suporte." /><PremiumCard icon="⌁" title="Automações" text="Liga eventos do servidor a ações personalizadas." /></div><button className="secondary" onClick={() => onOpen('#/features')}>Ver todas as funcionalidades</button></div></div></section>;
  const currentConfig = draft[current.key];
  const channels = context?.channels ?? [];
  const roles = context?.roles ?? [];
  const resourceName = current.key === 'welcome' ? '#boas-vindas' : current.key === 'roles' ? '#escolhe-cargos' : '#vozen-alertas';
  return <section className="quick-setup-page"><div className="quick-setup-head"><div><small className="eyebrow">QUICK SETUP · {index + 1} DE {quickSetupSteps.length}</small><h2>Configura o essencial do servidor.</h2><p>Aplicamos uma etapa de cada vez. Voltar não desfaz alterações já publicadas.</p></div><button className="link-button" onClick={onDismiss}>Sair por agora</button></div><div className="setup-progress" aria-label="Progresso da configuração">{quickSetupSteps.map((step, stepIndex) => <button key={step.key} className={stepIndex === index ? 'progress-step active' : state.steps.find((item) => item.key === step.key)?.status === 'applied' ? 'progress-step done' : 'progress-step'} onClick={() => stepIndex <= index && setIndex(stepIndex)}><span>{state.steps.find((item) => item.key === step.key)?.status === 'applied' ? '✓' : stepIndex + 1}</span><b>{step.label}</b></button>)}</div><div className="quick-setup-layout"><div className="quick-setup-form card"><small className="eyebrow">ETAPA {index + 1}</small><h3>{current.label}</h3><p className="setup-description">{current.description}</p>{current.key === 'welcome' && <><div className="choice-grid"><Choice selected={currentConfig.mode === 'recommended'} title="Mensagem recomendada" text="Uma receção curta, clara e pronta a usar." onClick={() => patch('mode', 'recommended')} /><Choice selected={currentConfig.mode === 'custom'} title="Personalizar" text="Escreve a tua mensagem e escolhe as opções." onClick={() => patch('mode', 'custom')} /><Choice selected={currentConfig.mode === 'off'} title="Desativar" text="Não publicar mensagens de entrada." onClick={() => patch('mode', 'off')} /></div>{currentConfig.mode !== 'off' && <><SelectField label="Canal de entrada" value={String(currentConfig.channel ?? '')} options={channels} placeholder="Escolhe um canal" onChange={(value) => patch('channel', value)} /><label className="field toggle-field"><span><b>Criar #boas-vindas se não existir</b><small>O Vozen mostra a criação no resumo antes de confirmar.</small></span><input type="checkbox" checked={Boolean(currentConfig.createChannel)} onChange={(event) => patch('createChannel', event.target.checked)} /></label><label className="field"><span><b>Mensagem pública</b><small>Podes usar {`{member}`} e {`{server}`}.</small></span><textarea rows={3} value={String(currentConfig.message ?? '')} onChange={(event) => patch('message', event.target.value)} /></label></>}</>}{current.key === 'roles' && <><div className="template-row"><b>Escolhe um ponto de partida</b><div>{[['notifications', 'Notificações'], ['interests', 'Interesses'], ['languages', 'Idiomas']].map(([id, label]) => <button key={id} className={currentConfig.template === id ? 'template selected' : 'template'} onClick={() => patch('template', id)}>{label}</button>)}</div></div><SelectField label="Canal do painel" value={String(currentConfig.channel ?? '')} options={channels} placeholder="Escolhe um canal" onChange={(value) => patch('channel', value)} /><label className="field toggle-field"><span><b>Criar #escolhe-cargos se não existir</b><small>Os cargos ficam sem permissões administrativas.</small></span><input type="checkbox" checked={Boolean(currentConfig.createChannel)} onChange={(event) => patch('createChannel', event.target.checked)} /></label><label className="field"><span><b>Nomes dos cargos</b><small>Separa os nomes por vírgulas.</small></span><input value={String(currentConfig.roleNames ?? '')} onChange={(event) => patch('roleNames', event.target.value)} /></label></>}{current.key === 'moderation' && <><SelectField label="Canal de registos" value={String(currentConfig.logChannel ?? '')} options={channels} placeholder="Escolhe um canal" onChange={(value) => patch('logChannel', value)} /><label className="field toggle-field"><span><b>Criar #vozen-alertas se não existir</b><small>Inclui ações do Helper e alterações importantes.</small></span><input type="checkbox" checked={Boolean(currentConfig.createChannel)} onChange={(event) => patch('createChannel', event.target.checked)} /></label><div className="field-grid"><label className="field"><span><b>Avisos antes de agir</b></span><input type="number" min={1} max={10} value={Number(currentConfig.warnThreshold ?? 3)} onChange={(event) => patch('warnThreshold', Number(event.target.value))} /></label><label className="field"><span><b>Timeout (minutos)</b></span><input type="number" min={0} max={10080} value={Number(currentConfig.timeoutMinutes ?? 10)} onChange={(event) => patch('timeoutMinutes', Number(event.target.value))} /></label></div><div className="notice warning">Esta etapa só será publicada quando o runtime de moderação estiver operacional.</div></>}{current.key === 'protection' && <><div className="choice-grid"><Choice selected={currentConfig.profile === 'monitor'} title="Monitorizar" text="Avisa a equipa sem castigar membros." onClick={() => patch('profile', 'monitor')} /><Choice selected={currentConfig.profile === 'balanced'} title="Equilibrado" text="Recomendado para a maioria dos servidores." onClick={() => patch('profile', 'balanced')} /><Choice selected={currentConfig.profile === 'strict'} title="Reforçado" text="Limites apertados para comunidades maiores." onClick={() => patch('profile', 'strict')} /></div><SelectField label="Canal de alertas" value={String(currentConfig.logChannel ?? '')} options={channels} placeholder="Escolhe um canal" onChange={(value) => patch('logChannel', value)} /><label className="field toggle-field"><span><b>Criar #vozen-alertas se não existir</b><small>O nome é apenas uma sugestão; revê-o antes de aplicar.</small></span><input type="checkbox" checked={Boolean(currentConfig.createChannel)} onChange={(event) => patch('createChannel', event.target.checked)} /></label><div className="notice">O perfil altera anti-spam e anti-raid com valores transparentes e reversíveis.</div></>}</div><aside className="quick-setup-aside card"><small className="eyebrow">ANTES DE APLICAR</small><h3>Pré-visualização</h3><div className="discord-preview"><span className="preview-avatar">✦</span><div><b>{current.key === 'roles' ? 'Painel de escolhas' : current.key === 'protection' ? 'Proteção do servidor' : current.key === 'moderation' ? 'Registo de moderação' : 'Bem-vindo ao servidor'}</b><p>{current.key === 'roles' ? 'Escolhe as opções que combinam contigo.' : current.key === 'protection' ? 'Perfil ' + String(currentConfig.profile ?? 'balanced') + ' · ações reversíveis.' : current.key === 'moderation' ? 'As ações da equipa ficam registadas.' : String(currentConfig.message ?? 'A tua comunidade começa aqui.')}</p></div></div>{Boolean(currentConfig.createChannel) && current.key !== 'protection' && <div className="resource-preview"><span>+</span><div><b>Criar {resourceName}</b><small>Será confirmado antes da publicação.</small></div></div>}{roles.length > 0 && current.key === 'roles' && <small className="muted-note">{roles.length} cargos disponíveis para reutilizar.</small>}<div className="sticky-actions"><button className="secondary" onClick={() => void skip()} disabled={applying}>Saltar</button><button className="primary" onClick={() => void apply()} disabled={applying}>{applying ? 'A aplicar…' : 'Confirmar e aplicar'}</button></div></aside></div></section>;
}

function Choice({ selected, title, text, onClick }: { selected: boolean; title: string; text: string; onClick: () => void }) { return <button type="button" className={selected ? 'setup-choice selected' : 'setup-choice'} onClick={onClick}><span className="choice-dot" /><div><b>{title}</b><small>{text}</small></div></button>; }
function SelectField({ label, value, options, placeholder, onChange }: { label: string; value: string; options: Array<{ id: string; name: string }>; placeholder: string; onChange: (value: string) => void }) { return <label className="field"><span><b>{label}</b><small>{options.length ? 'Seleciona um recurso existente.' : 'A leitura do Discord ainda não está disponível.'}</small></span><select value={value} onChange={(event) => onChange(event.target.value)}><option value="">{placeholder}</option>{options.map((option) => <option value={option.id} key={option.id}>#{option.name}</option>)}</select></label>; }
function PremiumCard({ icon, title, text }: { icon: string; title: string; text: string }) { return <article className="premium-card"><span>{icon}</span><b>{title}</b><p>{text}</p><small>Premium</small></article>; }

function AuthScreen({ error, loading, onLogin }: { error: string; loading: boolean; onLogin: () => void }) { const visibleError = /unauthenticated|API 401/i.test(error) ? '' : error; return <main className="auth-shell"><div className="auth-brand"><span>✦</span><div><strong>VOZEN</strong><small>HELPER PANEL</small></div></div><section className="auth-card card"><div className="auth-icon">✦</div><small className="eyebrow">ACESSO SEGURO</small><h1>Entra no teu painel</h1><p>Usa a tua conta Discord para gerir o Helper e configurar os teus servidores.</p><button className="primary auth-button" onClick={onLogin} disabled={loading}>{loading ? 'A ligar ao Discord…' : 'Continuar com Discord'}</button>{visibleError && <p className="auth-error" role="alert">{visibleError}</p>}<small className="auth-note">O acesso é protegido e só mostra servidores onde tens permissão de gestão.</small></section></main>; }

function Overview({ features, stats, quota, cases, onOpen }: { features: Feature[]; stats: { totalCases: number }; quota: { plan: string; limits: Record<string, number>; usage: Record<string, number> }; cases: CaseRecord[]; onOpen: (path: string) => void }) { const enabled = features.filter((feature) => feature.enabled).length; return <><section className="welcome card"><div><small className="eyebrow">CENTRO DE COMANDO</small><h2>O teu servidor, sob controlo.</h2><p>Vê o que precisa de atenção e configura o Helper por etapas simples. Cada alteração fica ligada ao teu servidor.</p><button className="primary" onClick={() => onOpen('#/features')}>Configurar o Helper</button></div><div className="setup-steps"><button onClick={() => onOpen('#/config/protection.antispam')}><span>1</span><div><b>Proteger o servidor</b><small>{enabled} funcionalidades ativas</small></div><em>›</em></button><button onClick={() => onOpen('#/config/support.welcome')}><span>2</span><div><b>Receber novos membros</b><small>Mensagem e cargo inicial</small></div><em>›</em></button><button onClick={() => onOpen('#/config/community.levels')}><span>3</span><div><b>Dar vida à comunidade</b><small>Níveis, XP e recompensas</small></div><em>›</em></button></div></section><div className="metrics"><Metric value={String(enabled)} label="funcionalidades ativas" /><Metric value={String(stats.totalCases)} label="casos de moderação" /><Metric value={String(cases.length)} label="eventos recentes" /><Metric value={quota.plan} label="plano atual" /></div><section className="section-heading"><div><small className="eyebrow">RECOMENDADO</small><h2>O que queres fazer primeiro?</h2></div><button className="link-button" onClick={() => onOpen('#/features')}>Ver tudo →</button></section><div className="quick-grid"><Quick icon="🛡" title="Proteger o servidor" text="Anti-spam, anti-raid e proteção de entradas." onClick={() => onOpen('#/config/protection.antispam')} /><Quick icon="✦" title="Dar vida à comunidade" text="Níveis, sugestões, sorteios e starboard." onClick={() => onOpen('#/config/community.levels')} /><Quick icon="▣" title="Criar identidade" text="Escolhe cores, tipografia e um banner seguro." onClick={() => onOpen('#/rank-card')} /></div><section className="quota card"><div><small className="eyebrow">LIMITE DO PLANO</small><h3>Usa o Helper com espaço para crescer</h3><p>O plano atual mostra os limites antes de uma ação ficar bloqueada.</p></div><div className="quota-items"><Quota label="Workflows" used={quota.usage.workflows ?? 0} limit={quota.limits.workflows ?? 0} /><Quota label="Templates" used={quota.usage.templates ?? 0} limit={quota.limits.templates ?? 0} /><Quota label="Role panels" used={quota.usage.role_panels ?? 0} limit={quota.limits.role_panels ?? 0} /></div></section></>; }
function Metric({ value, label }: { value: string; label: string }) { return <div className="metric card"><strong>{value}</strong><span>{label}</span></div>; }
function Quota({ label, used, limit }: { label: string; used: number; limit: number }) { const percent = limit > 0 ? Math.min(100, Math.round((used / limit) * 100)) : 0; return <div className="quota-item"><div><span>{label}</span><b>{used} / {limit || '—'}</b></div><i><em style={{ width: `${percent}%` }} /></i></div>; }
function Quick({ icon, title, text, onClick }: { icon: string; title: string; text: string; onClick: () => void }) { return <button className="quick card" onClick={onClick}><span className="quick-icon">{icon}</span><div><h3>{title}</h3><p>{text}</p></div><b>→</b></button>; }

function FeatureCatalogue({ features, filter, setFilter, search, setSearch, onOpen }: { features: Feature[]; filter: Category; setFilter: (value: Category) => void; search: string; setSearch: (value: string) => void; onOpen: (key: string) => void }) {
  return <section><div className="catalog-toolbar"><div><small className="eyebrow">CATÁLOGO DO HELPER</small><h2>Escolhe o que o teu servidor precisa</h2><p>Abre um tópico para veres opções essenciais, definições avançadas e uma simulação segura.</p></div><input className="search" value={search} onChange={(event) => setSearch(event.target.value)} placeholder="Pesquisar funcionalidade…" aria-label="Pesquisar funcionalidade" /></div><div className="filters">{categories.map((category) => <button key={category.id} className={filter === category.id ? 'filter active' : 'filter'} onClick={() => setFilter(category.id)}>{category.label}</button>)}</div><div className="feature-grid">{features.map((feature) => { const maturity = feature.maturity ?? (feature.available ? 'operational' : 'planned'); const configurable = feature.configurable ?? feature.available; const label = maturity === 'operational' ? (feature.enabled ? 'Ativa' : 'Disponível') : maturity === 'beta' ? 'Beta' : maturity === 'blocked' ? 'Bloqueada' : maturity === 'degraded' ? 'Com problemas' : 'Planeada'; return <article className="feature card" key={feature.key}><div className="feature-top"><span className={`feature-icon ${feature.category}`}>{feature.category === 'protection' ? '◈' : feature.category === 'community' ? '✦' : '▤'}</span><span className={feature.enabled && maturity === 'operational' ? 'pill on' : maturity === 'blocked' ? 'pill muted' : 'pill'}>{label}</span></div><h3>{feature.label}</h3><p>{feature.description}</p><button className="secondary full" disabled={!configurable} onClick={() => onOpen(feature.key)}>{feature.key === 'studio.rank_card' ? 'Personalizar' : configurable ? 'Configurar' : 'Ver plano'}</button></article>; })}</div>{!features.length && <div className="empty card">Não encontrámos funcionalidades com esse filtro.</div>}</section>;
}

function FeatureDetail({ feature, config, enabled, onEnabled, onChange, onSave, onDiscard, onTest, saving, onBack }: { feature?: Feature; config: FeatureConfig; enabled: boolean; onEnabled: (value: boolean) => void; onChange: (key: string, value: unknown) => void; onSave: () => void; onDiscard: () => void; onTest: () => void; saving: boolean; onBack: () => void }) {
  const sections = spec(feature?.key ?? '');
  const configurable = feature?.configurable ?? true;
  if (!configurable) return <section className="detail-page"><button className="back-link" onClick={onBack}>← Voltar às funcionalidades</button><div className="detail-intro card"><small className="eyebrow">ROADMAP</small><h2>{feature?.label ?? 'Funcionalidade'}</h2><p>{feature?.description ?? 'Esta área está no plano do Vozen Helper.'}</p><p className="tip">Ainda não existe um adaptador operacional para este servidor. Não há ativação disponível até a integração, permissões e rollback estarem prontos.</p></div></section>;
  return <section className="detail-page"><button className="back-link" onClick={onBack}>← Voltar às funcionalidades</button><div className="detail-intro card"><div><small className="eyebrow">CONFIGURAÇÃO · {feature?.category === 'protection' ? 'PROTEÇÃO' : feature?.category === 'community' ? 'COMUNIDADE' : 'GESTÃO'}</small><h2>{feature?.label ?? 'Funcionalidade'}</h2><p>{feature?.description ?? 'Ajusta esta funcionalidade ao teu servidor.'}</p></div><label className="switch-row"><span><b>{enabled ? 'Ativa' : 'Desativada'}</b><small>O Helper aplica esta configuração no servidor.</small></span><input type="checkbox" checked={enabled} onChange={(event) => onEnabled(event.target.checked)} /></label></div><div className="detail-layout"><div className="detail-sections">{sections.map((section) => <ConfigSection key={section.title} section={section} config={config} onChange={onChange} />)}</div><aside className="detail-aside card"><div><small className="eyebrow">ANTES DE PUBLICAR</small><h3>Confere sem risco</h3><p>Usa a simulação para veres o que aconteceria. Ela nunca apaga mensagens nem castiga membros.</p></div><button className="secondary full" onClick={onTest}>Simular configuração</button><div className="tip"><b>Precisas de ajuda?</b><span>Os campos avançados estão fechados para manter o primeiro passo simples.</span></div></aside></div><div className="sticky-actions"><button className="secondary" onClick={onDiscard} disabled={saving}>Descartar</button><button className="primary" onClick={onSave} disabled={saving}>{saving ? 'A guardar…' : 'Guardar alterações'}</button></div></section>;
}
function ConfigSection({ section, config, onChange }: { section: SectionSpec; config: FeatureConfig; onChange: (key: string, value: unknown) => void }) { const advanced = section.fields.filter((field) => field.advanced); const basic = section.fields.filter((field) => !field.advanced); return <section className="config-section card"><div className="section-heading"><div><small className="eyebrow">CONFIGURAÇÃO</small><h3>{section.title}</h3><p>{section.description}</p></div></div><div className="field-grid">{basic.map((field) => <FieldControl field={field} key={field.key} value={config[field.key]} onChange={onChange} />)}</div>{advanced.length > 0 && <details className="advanced"><summary>Opções avançadas <span>{advanced.length} definições</span></summary><div className="field-grid">{advanced.map((field) => <FieldControl field={field} key={field.key} value={config[field.key]} onChange={onChange} />)}</div></details>}</section>; }
function FieldControl({ field, value, onChange }: { field: FieldSpec; value: unknown; onChange: (key: string, value: unknown) => void }) { const normalized = value ?? (field.kind === 'toggle' ? false : field.kind === 'tags' ? [] : ''); if (field.kind === 'toggle') return <label className="field toggle-field"><span><b>{field.label}</b>{field.help && <small>{field.help}</small>}</span><input type="checkbox" checked={Boolean(normalized)} onChange={(event) => onChange(field.key, event.target.checked)} /></label>; if (field.kind === 'textarea') return <label className="field"><span><b>{field.label}</b>{field.help && <small>{field.help}</small>}</span><textarea value={String(normalized)} onChange={(event) => onChange(field.key, event.target.value)} rows={3} /></label>; if (field.kind === 'tags') return <label className="field"><span><b>{field.label}</b><small>{field.help ?? 'Separa vários valores por vírgulas.'}</small></span><input value={Array.isArray(normalized) ? normalized.join(', ') : String(normalized)} onChange={(event) => onChange(field.key, event.target.value.split(',').map((item) => item.trim()).filter(Boolean))} /></label>; if (field.kind === 'select') return <label className="field"><span><b>{field.label}</b>{field.help && <small>{field.help}</small>}</span><select value={String(normalized)} onChange={(event) => onChange(field.key, event.target.value)}>{field.options?.map(([option, label]) => <option value={option} key={option}>{label}</option>)}</select></label>; return <label className="field"><span><b>{field.label}</b>{field.help && <small>{field.help}</small>}</span><input type={field.kind} min={field.min} max={field.max} maxLength={field.maxLength} step={field.step ?? 1} value={field.kind === 'number' ? Number(normalized) : String(normalized)} onChange={(event) => onChange(field.key, field.kind === 'number' ? Number(event.target.value) : event.target.value)} /></label>; }

function Activity({ cases, audit }: { cases: CaseRecord[]; audit: AuditRecord[] }) { return <section className="activity"><div className="section-heading"><div><small className="eyebrow">TRANSPARÊNCIA</small><h2>Atividade recente</h2><p>Cada ação mostra o que aconteceu sem esconder detalhes importantes.</p></div></div><div className="table card"><div className="table-head"><span>Ação</span><span>Alvo / ator</span><span>Estado</span><span>Data</span></div>{cases.map((item) => <div className="table-row" key={`case-${item.id}`}><span><b className="tag danger">{item.kind ?? item.type ?? 'moderação'}</b></span><span>{item.target_id ?? item.targetId ?? '—'}</span><span>{item.reason || 'Sem motivo indicado'}</span><span>{formatDate(item.created_at ?? item.createdAt)}</span></div>)}{audit.map((item, index) => <div className="table-row" key={`audit-${index}`}><span><b className="tag">{item.action}</b></span><span>{item.actor_id ?? item.actorId ?? '—'}</span><span>{item.outcome}</span><span>{formatDate(item.created_at)}</span></div>)}{!cases.length && !audit.length && <div className="empty">Ainda não há atividade para mostrar.</div>}</div></section>; }
function formatDate(value?: number | string) { if (!value) return '—'; const date = typeof value === 'number' ? new Date(value < 2_000_000_000 ? value * 1000 : value) : new Date(value); return Number.isNaN(date.valueOf()) ? '—' : date.toLocaleString('pt-PT', { dateStyle: 'short', timeStyle: 'short' }); }

function RankCardEditor({ config, patch, onSave, onReset, saving }: { config: RankCardConfig; patch: (next: Partial<RankCardConfig>) => void; onSave: () => void; onReset: () => void; saving: boolean }) { return <section className="editor-grid"><div className="card preview-panel"><div className="card-title"><div><small className="eyebrow">PRÉ-VISUALIZAÇÃO AO VIVO</small><h2>Assim aparece no Discord</h2></div><span className="live-dot">● ao vivo</span></div><RankPreview config={config} /></div><div className="card controls"><div className="card-title"><div><small className="eyebrow">EDITOR SEGURO</small><h2>Identidade do XP card</h2><p>Usa apenas banners curados pelo Vozen ou uma cor sólida.</p></div></div><label>Fonte<select value={config.font} onChange={(event) => patch({ font: event.target.value })}><option value="system">System</option><option value="inter">Inter</option><option value="roboto">Roboto</option><option value="poppins">Poppins</option><option value="space_grotesk">Space Grotesk</option><option value="lexend">Lexend</option></select></label><ColorField label="Cor principal" value={config.primary_color} swatches={swatches} onChange={(value) => patch({ primary_color: value, avatar_ring_color: value })} /><ColorField label="Cor do texto" value={config.text_color} swatches={swatches} onChange={(value) => patch({ text_color: value })} /><label>Opacidade do overlay <output>{Math.round(config.overlay_opacity * 100)}%</output><input type="range" min="0" max="0.85" step="0.01" value={config.overlay_opacity} onChange={(event) => patch({ overlay_opacity: Number(event.target.value) })} /></label><BackgroundPicker config={config} patch={patch} /><div className="actions"><button className="secondary" onClick={onReset}>Restaurar</button><button className="primary" onClick={onSave} disabled={saving}>{saving ? 'A guardar…' : 'Guardar alterações'}</button></div></div></section>; }
function BackgroundPicker({ config, patch }: { config: RankCardConfig; patch: (next: Partial<RankCardConfig>) => void }) { const preset = config.background_preset; return <div className="background-picker"><div className="field-label"><span>Fundo do XP card</span><small>{preset ? 'Banner curado' : 'Cor sólida'}</small></div><div className="background-modes"><button type="button" className={!preset ? 'mode selected' : 'mode'} onClick={() => patch({ background_preset: null, background_url: null, background_data: null })}>Cor sólida</button><button type="button" className={preset ? 'mode selected' : 'mode'} onClick={() => patch({ background_preset: preset ?? presetOptions[0][0], background_url: null, background_data: null })}>Banners</button></div>{preset ? <div className="banner-grid">{presetOptions.map(([id, label, path]) => <button type="button" className={preset === id ? 'banner-option selected' : 'banner-option'} key={id} onClick={() => patch({ background_preset: id, background_url: null, background_data: null })}><img src={path} alt="" /><span>{label}</span></button>)}</div> : <ColorField label="Escolhe uma cor de fundo" value={config.background_color} swatches={['#101725', '#172033', '#1F2937', '#312E46', '#3B2434', '#243A36']} onChange={(value) => patch({ background_color: value })} />}</div>; }
function ColorField({ label, value, swatches: colors, onChange }: { label: string; value: string; swatches: string[]; onChange: (value: string) => void }) { return <div className="color-field"><div className="field-label"><span>{label}</span><input type="color" value={value} onChange={(event) => onChange(event.target.value.toUpperCase())} /></div><div className="swatches">{colors.map((color) => <button type="button" aria-label={color} key={color} className={color.toLowerCase() === value.toLowerCase() ? 'swatch selected' : 'swatch'} style={{ background: color }} onClick={() => onChange(color)} />)}</div></div>; }
function RankPreview({ config }: { config: RankCardConfig }) { const background = presetOptions.find(([id]) => id === config.background_preset)?.[2]; const backgroundImage = background ? `linear-gradient(rgba(0,0,0,${config.overlay_opacity}), rgba(0,0,0,${config.overlay_opacity})), url(${JSON.stringify(background)})` : undefined; return <div className="rank-preview" style={{ backgroundColor: config.background_color, backgroundImage, fontFamily: config.font === 'system' ? 'system-ui' : config.font.replace('_', ' ') }}><div className="rank-avatar" style={{ borderColor: config.avatar_ring_color, borderWidth: config.avatar_ring_width }}><span>✦</span></div><div className="rank-content"><div className="rank-top"><strong style={{ color: config.text_color }}>Lunara</strong><div><b style={{ color: config.primary_color }}>Rank #17</b><b style={{ color: config.text_color }}>Level 8</b></div></div><p style={{ color: config.primary_color }}>lunara#4821</p><div className="xp-meta"><span style={{ color: config.text_color }}>429 / 1337 XP</span><span style={{ color: config.text_color }}>32%</span></div><div className="xp-track"><i style={{ background: config.primary_color, width: '32%' }} /></div></div></div>; }

export default App;
